def get_pos(name):
    r = primitives.call(name="locate_robocasa_object", object_name=name)
    if r.ok and isinstance(r.output, dict):
        for k in ["position", "world_position", "pose", "center"]:
            if k in r.output and r.output[k]:
                return r.output[k][:3]
        if "data" in r.output and isinstance(r.output["data"], dict):
            for k in ["position", "world_position"]:
                if k in r.output["data"]:
                    return r.output["data"][k][:3]
    g = primitives.call(name="ground_robocasa_visual_target", entity_name=name)
    if g.ok and isinstance(g.output, dict):
        for k in ["world_position", "position", "center"]:
            if k in g.output and g.output[k]:
                return g.output[k][:3]
    return None

